public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    long totalSum = 0;
    for (int v : nums) totalSum += v;
    java.util.List<java.util.HashSet<Integer>> subsets = new java.util.ArrayList<>(n + 1);
    for (int i = 0; i <= n; i++) subsets.add(new java.util.HashSet<>());
    subsets.get(0).add(0);
    for (int num : nums) {
        for (int sz = n - 1; sz >= 1; sz--) {
            java.util.Set<Integer> prevSet = subsets.get(sz - 1);
            java.util.HashSet<Integer> curSet = subsets.get(sz);
            if (prevSet.isEmpty()) continue;
            if (totalSum * sz % n == 0) {
                int target = (int) (totalSum * sz / n);
                for (int pre : prevSet) {
                    int newSum = pre + num;
                    if (newSum == target) return true;
                    curSet.add(newSum);
                }
            } else {
                for (int pre : prevSet) {
                    curSet.add(pre + num);
                }
            }
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    // dp[i] represents the minimum cost to reach step i
    // We only need the previous two values
    int prevTwo = 0; // dp[i-2]
    int prevOne = 0; // dp[i-1]
    for (int i = 2; i <= n; i++) {
        int current = Math.min(prevTwo + cost[i - 2], prevOne + cost[i - 1]);
        prevTwo = prevOne;
        prevOne = current;
    }
    return prevOne;
}

