    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else { // c == ')'
            if (balance == 0) {
                res++; // insert a '(' before this ')'
            } else {
                balance--; // match this ')'
            }
        }
    }
    res += balance; // insert ')' for unmatched '('
    return res;
}

