    }
    int m = mat.length;
    int n = mat[0].length;
    int total = m * n;
    int[] result = new int[total];
    int index = 0;

    for (int d = 0; d < m + n - 1; d++) {
        int startRow, startCol;
        if (d < m) {
            startRow = d;
            startCol = 0;
        } else {
            startRow = m - 1;
            startCol = d - m + 1;
        }

        int r = startRow;
        int c = startCol;

        // If the diagonal index is even, traverse from bottom to top
        if (d % 2 == 0) {
            while (r >= 0 && c < n) {
                result[index++] = mat[r][c];
                r--;
                c++;
            }
        } else { // odd index: top to bottom
            while (r < m && c >= 0) {
                result[index++] = mat[r][c];
                r++;
                c--;
            }
        }
    }

    return result;
}

