public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    int[] ugly = new int[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    int next2 = 2, next3 = 3, next5 = 5;
    for (int i = 1; i < n; i++) {
        int nextUgly = Math.min(next2, Math.min(next3, next5));
        ugly[i] = nextUgly;
        if (nextUgly == next2) {
            i2++;
            next2 = ugly[i2] * 2;
        }
        if (nextUgly == next3) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }
    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    /**
     * Calculates the energy of the string, defined as the length of the longest
     * contiguous substring containing only one repeated character.
     *
     * @param s The input string.
     * @return The energy of the string. Returns 0 if the input string is null or empty.
     */
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int maxLen = 1;
    int currentLen = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentLen++;
            if (currentLen > maxLen) {
                maxLen = currentLen;
            }
        } else {
            currentLen = 1;
        }
    }
    return maxLen;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> res = new ArrayList<>();
    int cur = 1;
    for (int i=0; i<n; i++) {
        res.add(cur);
        if (cur * 10 <= n) {
            cur *= 10;
        } else if (cur % 10 != 9 && cur / 10 < n) {
            cur += 1;
        } else {
            while ((cur % 10 == 9) || (cur / 10 == 0)) {
                cur /= 10;
            }
            cur += 1;
        }
    }
    return res;
}

